#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = path.join(ROOT, 'output');
const BLOCK = '**** YD001 SOURCE BLOCK ****';
const ENG = '**** ENGLISH ****';
const END = '**** END BLOCK ****';

function patchFile(rel, slug, T) {
  const fp = path.join(OUT, rel);
  const s = fs.readFileSync(fp, 'utf8');
  const applied = new Set();
  const parts = s.split(BLOCK);
  const out = parts.map((block, i) => {
    if (i === 0) return block;
    const slugM = block.match(/^\s*slug: (.+)$/m);
    const seifM = block.match(/^\s*seif: (.+)$/m);
    const markerM = block.match(/^\s*marker: (.+)$/m);
    if (!slugM || slugM[1].trim() !== slug) return BLOCK + block;
    const seif = seifM[1].trim();
    const marker = markerM ? markerM[1].trim() : 'main';
    const key = `${seif}#${marker}`;
    if (!(key in T)) return BLOCK + block;
    const enStart = block.indexOf(ENG);
    const enEnd = block.indexOf(END);
    if (enStart < 0 || enEnd < 0) throw new Error(`ENGLISH/END missing: ${rel} ${key}`);
    const before = block.slice(0, enStart + ENG.length + 1);
    const after = block.slice(enEnd);
    const text = T[key].endsWith('\n') ? T[key] : T[key] + '\n';
    applied.add(key);
    return BLOCK + before + text + after;
  });
  const missing = Object.keys(T).filter((k) => !applied.has(k));
  if (missing.length) throw new Error(`Keys not found in ${rel}: ${missing.join(', ')}`);
  fs.writeFileSync(fp, out.join(''), 'utf8');
  console.log(`OK ${rel} (${applied.size} blocks)`);
}

// --- mechaber (3) ---
patchFile('siman_015/mechaber/part-001.txt', 'mechaber', {
  '1#main': `Not to slaughter an animal until the eighth day from its birth. In it are 3 seifim. A chick—all the time it has not gone out into the air of the world is forbidden; and after it goes out into the air of the world it is permitted immediately.`,
  '2#main': `An animal that gave birth—if it is known that its months are completed—that is, nine months for a large animal and five for a small one—it is permitted immediately on the day it was born; and we are not concerned lest its limbs were crushed (meaning: were smashed and broken) from the pains of birth. And if it is not known that its months are completed—it is forbidden because of doubt of stillborn until the beginning of the eighth night.`,
  '3#main': `We do not rely on a gentile regarding small kids purchased from him who says they are eight days old (responsa of Rashba siman 243).`,
});

// --- siftei-kohen (4) ---
patchFile('siman_015/siftei-kohen/part-001.txt', 'siftei-kohen', {
  '1#א': `<b>Forbidden.</b> Because of "the creeping thing that creeps upon the earth" (Tur)—for even its creeping within its shell is called creeping; and see below siman 66 seif 2 and siman 86 seif 8.`,
  '1#ב': `<b>Permitted immediately.</b> Even if its eyes have not opened (Beit Yosef in name of most poskim). However, Hagahot Maor wrote from Or Zarua that because of "abomination you shall not eat it" one may not eat until wings grow—that is, large feather on its body that has quills; for all birds whose wings have not grown, Rabbi Yoel forbade because of sheketz—end of his words; and so Or HaChaim kelal 55 din 11; and so later authorities.`,
  '2#_': `<b>And we are not concerned, etc.</b> And even if there is a deficiency that it does not walk (Tosafot); and so Rosh and Tur siman 58 and Rabbeinu Yerucham netiv 15 ot 16—that even if it cannot stand it is permitted; and as Beit Yosef—even if she struggles to give birth; and so Shaltiei Gibborim in name of poskim; and see siman 58 and Orach Chaim siman 498 seif 5 and what is written there.`,
  '3#_': `<b>We do not rely, etc.</b> For a gentile is not believed except in woman's testimony alone; and all the more here where he speaks to enhance his merchandise (so Rashba in responsa siman 243); and therefore even a gentile speaking mesisach l'fi tumo is not believed—for regarding woman's testimony we rule he is not believed except mesisach l'fi tumo, as explained in Orach Chaim siman 17 and see siman 16 seif 11 and siman 98 s.k. 2 from this.`,
});

// --- turei-zahav (4) ---
patchFile('siman_015/turei-zahav/part-001.txt', 'turei-zahav', {
  '1#_': `<b>Into the air of the world.</b> In first chapter of Beitzah (daf 6) R' Eliezer ben Yaakov and the rabbis dispute: R' Eliezer ben Yaakov holds "all the creeping thing that creeps upon the earth" includes chicks whose eyes have not opened; and the rabbis hold all the time it has not gone out into the air of the world; and the Rif ruled like the rabbis. And the Ran wrote: even though we rule mishnat R' Elazar ben Azarya kav v'naki, nevertheless since R' Yochanan is established like the rabbis and Rav like R' Eliezer ben Yaakov, and we rule Rav and R' Yochanan—the halachah is like R' Yochanan. And it is difficult: what is the superiority of this principle over that principle of mishnat R' Elazar ben Azarya kav v'naki. And it appears we revoke this because of that and return to the principle of individual and many—the halachah is like the many; and so the Rosh in first chapter and so here Tur and Shulchan Aruch. And one may wonder on the Rosh who rules in first chapter of Beitzah like R' Eliezer ben Yaakov and contradicts his words in first chapter—and I wrote this because I saw in Hagahot Ashiri first chapter of Beitzah: "and such as one born with wings—that is, large feather on its body that has quills; but birds whose wings have not grown, Rabbi Yoel forbade because of sheketz, Or Zarua"—end of his words; and Maran z"l brought this hagahah to halachah. And I wonder on Rabbi Yoel who forbade because of sheketz—like whom does he hold. And it appears to me he holds like R' Eliezer ben Yaakov; and the measure of eyes opened and measure of wings grown are one measure; and if so, according to what Shulchan Aruch ruled like the rabbis, we do not rule also like this hagahah of Ashiri.`,
  '2#א': `<b>And we are not concerned lest they were crushed, etc.</b> In the Gemara Rav Nachman said: the womb has no concern of crushing limbs—Rashi explained we are not concerned lest they were pressed and limbs crushed, and one need not wait from time to time; and he sought to bring support from the beraisa of a calf born on Yom Tov that it is permitted to slaughter it, and they rejected it—perhaps there it is different, for it deals with one that spread on the ground—Rashi: it kicked to stand and extended its hooves to stand; for we say later regarding a fallen animal: if it stood from its fall, one need not wait from time to time—automatically according to truth one need not spread; and from this Rabbeinu Yerucham and Mahari ibn Chaviv and Maharil in Likutim brought in his name, and Beit Yosef in Orach Chaim siman 498 on what the Rosh wrote in first chapter of Beitzah: "and that which he permitted to eat it on the day of birth—that is where it is established that its months are completed; but if it is not established that its months are completed, it is forbidden until the night of the eighth, as stated in chapter R' Eliezer of Milah; and also it must spread on the ground because of doubt of crushing limbs, as stated in first chapter"—end of his words; and so the Tur wrote there; and this is against the halachah—for in truth one need not spread. And Beit Yosef answered there in name of Mahari ibn Chaviv that regarding Yom Tov the Rosh was more stringent; and so Rama wrote there that there is concern lest a deficiency be found in inner organs and one will slaughter not for need. And he was not precise in this—for the Talmud in chapter 4 of Beitzah (daf 34) asked: R' Yirmiyah from R' Zeira—what is the law to slaughter on Yom Tov an animal crushed in a wall that needs checking lest its limbs were crushed—do we presume deficiency, lest a treifah be found and one slaughter not for need. Rashi: granted other animals—even though we are stringent and check, nevertheless we rely on majority that they are not treifot; here on Yom Tov what. He said: we taught one may not whiten roof tiles on Yom Tov because they need checking and we are concerned lest they crack—apparently we are concerned and presume deficiency. He said: we answer because they need to be sealed—we answer not because of cracking but certainly one makes it a vessel through this heating. And behold the matter is a fortiori: for there on a weekday it is forbidden without checking and you have no majority for permission—specifically regarding other animals there is majority for permission as Rashi explained; not so regarding crushed; and nevertheless we slaughter on Yom Tov this calf that on a weekday needs no checking and has no concern at all—and most of them are fit for permission; and why be more stringent on Yom Tov. And he said: there with crushed it had a good presumption when born, unlike here. And this is not so—for if so, what did R' Zeira resolve from checking roof tiles—for there too there was no good presumption whether they crack or not. And further, here with a calf one need not any presumption at all, for there is no doubt here, and it is like other animals whose majority are fit, as Rashi explained—and better than them, for one need not check at all. All this seems simple; except I saw Maran z"l in Orach Chaim siman 494 corrected Rama's words here and wrote it appears regarding crushed in a wall it is permitted to slaughter on Yom Tov as the Tur wrote—that there is good presumption from birth and we follow majority of animals that are fit, and without doubt he did not examine the Gemara then for the reason I mentioned; and on the contrary it is proved that here with crushed there is no majority for permission—for if so, what is different from other animals, as Rashi explained explicitly, and there is no place for such stringency. And I heard one who wished to answer that requiring spreading is because of concern lest it fell from the womb to the ground—and Rav Nachman deals with one we saw was born. And this is mistaken—for falling forbids only from ten handbreadths, as written siman 58 seif 1; and even though we rule there that if others cast it down even in less than ten we are concerned—that is when others threw it with force, unlike here in birth. And besides, what relevance has falling to birth—for the animal crouches to give birth. And I saw Maharshal in first chapter seif 63: "and what shall I do that they all did not understand the Rosh's words and read his words and did not examine and erred—for what the Rosh wrote 'and it must spread,' etc., refers to what he wrote that if its months are not completed it is forbidden until the eighth night and also must spread,' etc.—for Rav Nachman did not say we are not concerned for crushing limbs even when there is deficiency, only when its months are completed; but without completion we are concerned, as the Rokeach wrote in name of rabbis of Speyer; and even waiting from time to time does not help when there is deficiency that it did not stand"—end of his words. And I say: his great honor rests in its place, and here he was not precise at all: first, the Rosh wrote as stated in first chapter and there nothing was mentioned of "its months completed"—how bring proof to infer regarding without completed months that waiting from time to time does not help, only spreading. And further, he mixed two matters that have no relation to each other—for requiring completed months is to remove doubt of stillborn as stated explicitly in chapter R' Eliezer of Milah (Shabbat daf 136)—all the halachah that whoever did not wait eight days is doubt stillborn, and we say there whoever completed months is removed from doubt stillborn; but there is no reason to say that since months are not completed there is concern of crushing limbs—this is impossible to say, since the womb has no concern of crushing limbs, why should there be crushing limbs without completed months. And who is the prophet who will tell us a distinction between birth of offspring whose months completed and whose months did not. Rather certainly whoever did not complete months and is removed from doubt stillborn through waiting seven days certainly need not spread, etc.; and so explained in Ran first chapter that there is no crushing in the womb even without completion—only concern is stillborn. And clear proof from that stated in chapter R' Eliezer of Milah: Rav Pappa and Rav Huna son of R' Yehoshua came to the house of Rav Idi; he made for them a third-grown calf on the seventh day. They said to him: if you had waited until evening we would have eaten from it, etc.—behold they objected only to not waiting until the eighth day; and had he waited they would eat even without seeing it spread and without asking at all—certainly spreading is unnecessary, for the womb has no concern of crushing limbs. And what the rabbi brought as proof from Sefer Rokeach—I wonder what the holy mouth thought—for there siman 468 the Rokeach brings: "and so I saw my father forbade a calf slaughtered within eight days; and he said: certainly if we knew clearly its months were completed it would be permitted, etc.; but now that it is unknown it is forbidden; and so all rabbis of Speyer ruled"—end of his words—behold he forbade only within eight days; but he mentioned nothing that after eight days one needs spreading on the ground—any hint or allusion. And apart from all this, it is astonishing on the rabbi's view—for wherever there is concern of crushing limbs, waiting from time to time helps at least, as standing is explained in siman 58; and explicitly they said in the Gemara: if it stood, one need not from time to time—learn from this that from time to time is better to remove doubt of crushing limbs; and nowhere in the world do we find waiting from time to time does not help—only specifically standing did not enter anyone's mind and will never enter the heart; and so explained here that after seven days nothing more is needed. And if so, why forbidden without completed months after it waited seven times from time to time—and only standing would make permission. And certainly the rabbi wrote thus in haste; and in truth the great ones did not err at all in this question, and the truth is as Rabbeinu Yerucham wrote that there is a printing error in the Rosh's words in what he required spreading, etc.; and the Tur followed him in mere transmission and copying; and the truth is as written here that if months completed one need not spread, and so if not completed and it waited seven days one need not spread at all—as explained, clear for halachah and practice; and the rabbi Maharshal did not fulfill his obligation of all examination in this.`,
  '2#ב': `<b>Until the beginning of the eighth night.</b> And even though regarding korban it is written "from the eighth day and onward"—korban is different, for it is not fit to be offered at night, since every korban is specifically by day.`,
  '3#_': `<b>We do not rely on a gentile, etc.</b> It is difficult—for behold it is a double doubt: doubt whether its months completed, and if you say not completed, doubt whether it has eight days. One may say he holds like the one who says in siman 110 seif 8 that in a davar sheyesh lo matirin a double doubt does not help. However it is difficult on Rama who wrote there that for need one may be lenient; and so Taz end of siman 70 in name of Ran to be lenient in a double doubt in a thing that has permission—and he should have permitted here too even without gentile reliability. And one may say a double doubt is not relevant here—for in any case there is doubt of stillborn or not, and you cannot say "if you find to say stillborn"—and this is not similar to doubt of adultery in first chapter of Kesubos in Tosafot.`,
});

// --- baer-heitev (5) ---
patchFile('siman_015/baer-heitev/part-001.txt', 'baer-heitev', {
  '1#א': `<b>Forbidden.</b> Because of "the creeping thing that creeps upon the earth"—for even its creeping within the shell is called creeping; and see below siman 66 seif 2 and siman 86 seif 8.`,
  '1#ב': `<b>Immediately.</b> And he wrote in Shach: even if its eyes have not opened; however there is to forbid because of sheketz and one may not eat until wings grow—that is, large feather on its body that has quills; for all birds whose wings have not grown are forbidden.`,
  '2#א': `<b>The birth.</b> And Shach wrote: even if there is deficiency that it does not walk, and even if it cannot stand—it is permitted, and even if it did not spread.`,
  '2#ב': `<b>Eighth.</b> And Taz wrote: then it is permitted even if it did not spread; and even though regarding korban it is written "and from the eighth day and onward"—korban is different, for it is not fit for offering at night.`,
  '3#_': `<b>Days.</b> And Taz wrote: and we do not say it is a double doubt as Rama wrote in siman 110 seif 8—because a double doubt is not relevant here, for in any case there is doubt of stillborn or not, and you cannot say "if you find to say stillborn," and this is not similar to doubt of adultery in first chapter of Kesubos. And Shach wrote: even if the gentile speaks mesisach l'fi tumo he is not believed—for only in woman's testimony alone, all the more here where it is to enhance his merchandise; and see below siman 16 seif 11 and siman 98.`,
});

